{
  "findings": [
    {
      "title": "Cross-reference to non-existent Section 8.3.11",
      "page": 85,
      "quote": "see Section 8.3.11.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.2.9",
      "page": 86,
      "quote": "Additional details are given in Section 8.2.9.",
      "severity": "major"
    },
    {
      "title": "Inconsistent PK sample disposal timeline",
      "page": 85,
      "quote": "PK samples will be disposed of after the Bioanalytical Report finalization or 6 months after issuance of the draft Bioanalytical Report (whichever is earlier)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent storage duration for biomarker samples",
      "page": 85,
      "quote": "Samples will be stored for a maximum of 15 years from the date of the issue of the CSR",
      "severity": "minor"
    },
    {
      "title": "Inconsistent storage duration for ADA samples",
      "page": 85,
      "quote": "Remaining ADA sample aliquots will be retained at AstraZeneca or its designee for a maximum of 15 years following issue of the CSR.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent storage duration for biomarker samples in Section 8.6",
      "page": 86,
      "quote": "Samples will be stored for a maximum of 15 years from the date of the issue of the CSR",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PK sampling schedule for Cycle 1",
      "page": 85,
      "quote": "PK sampling on Cycle 1 will be pre-dose (should not exceed 6 hours prior to start of infusion), post-infusion (within 15 minutes after the end of T-DXd infusion), and 5 hours (± 2 hours) post-infusion.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PK sampling schedule for Cycle 2 and Cycle 4",
      "page": 85,
      "quote": "PK sampling on Cycle 2 and Cycle 4 will be pre-dose (should not exceed 6 hours prior to start of infusion) and post-infusion (within 15 minutes after the end of T-DXd infusion).",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ADA sampling schedule",
      "page": 86,
      "quote": "Blood Samples will be taken within 8 hours before administration on Day 1 of Cycles 1 Cycle 2 and Cycle 4, and then every 4 cycles and EOT and Follow up.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about mandatory samples from screen failures",
      "page": 87,
      "quote": "The following mandatory samples will be collected from all patients including screen failures wherever possible.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about HER2 mutation testing",
      "page": 88,
      "quote": "HER2 activating mutations for eligibility will be based on local assessment. Patients who are eligible based on local assessment will also have HER2 status confirmed by retrospective central testing.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about biomarker data sharing",
      "page": 89,
      "quote": "AstraZeneca will not provide biomarker research results to patients, their family members, any insurance company, an employer, Investigators, general physician, or any other third party, unless required to do so by law.",
      "severity": "minor"
    }
  ]
}
